test('step: bounce off the bottom of a brick (hits while going UP)', () => {
  const state = createState(1);
  state.bricks = [{ x: 300, y: 100, w: 100, h: 20, alive: true }];
  state.ball = { x: 350, y: 121, r: 7, vx: 0, vy: -100 }; // Ball just below the brick, moving UP
  step(state, 1 / 60); // Moves ball to y = 121 - 1.66 = 119.33 (overlaps brick bottom)
  assert.ok(state.ball.vy > 0, 'Ball should bounce DOWN');
  assert.ok(state.ball.y >= 120 + 7, 'Ball should be pushed out of the brick');
});

test('step: bounce off the top of a brick (hits while going DOWN)', () => {
  const state = createState(1);
  state.bricks = [{ x: 300, y: 100, w: 100, h: 20, alive: true }];
  state.ball = { x: 350, y: 98, r: 7, vx: 0, vy: 100 }; // Ball just above the brick, moving DOWN
  step(state, 1 / 60); // Moves ball to y = 98 + 1.66 = 99.66 (overlaps brick top)
  assert.ok(state.ball.vy < 0, 'Ball should bounce UP');
  assert.ok(state.ball.y <= 100 - 7, 'Ball should be pushed out of the brick');
});

test('step: bounce off the left side of a brick (hits while going RIGHT)', () => {
  const state = createState(1);
  state.bricks = [{ x: 300, y: 100, w: 100, h: 20, alive: true }];
  state.ball = { x: 298, y: 110, r: 7, vx: 100, vy: 0 }; // Ball just left of the brick, moving RIGHT
  step(state, 1 / 60); // Moves ball to x = 298 + 1.66 = 299.66 (overlaps brick left)
  assert.ok(state.ball.vx < 0, 'Ball should bounce LEFT');
  assert.ok(state.ball.x <= 300 - 7, 'Ball should be pushed out of the brick');
});

test('step: bounce off the right side of a brick (hits while going LEFT)', () => {
  const state = createState(1);
  state.bricks = [{ x: 300, y: 100, w: 100, h: 20, alive: true }];
  state.ball = { x: 402, y: 110, r: 7, vx: -100, vy: 0 }; // Ball just right of the brick, moving LEFT
  step(state, 1 / 60); // Moves ball to x = 402 - 1.66 = 400.33 (overlaps brick right)
  assert.ok(state.ball.vx > 0, 'Ball should bounce RIGHT');
  assert.ok(state.ball.x >= 400 + 7, 'Ball should be pushed out of the brick');
});

test('step: tunnelling (ball skips over brick in one frame)', () => {
  const state = createState(1);
  state.bricks = [{ x: 300, y: 100, w: 100, h: 20, alive: true }];
  // Ball at y=130, vy=-1000. In 1/60s, it moves 16.6px.
  // Wait, the issue says at level 6, speed is 710 px/s.
  // Let's use a very high speed to be sure.
  state.ball = { x: 350, y: 130, r: 7, vx: 0, vy: -2000 }; // Moves 33.3px per frame
  // Starting pos: y=130 (ball bottom at 137, top at 123). Brick bottom at 120.
  // After step: y=130 - 33.3 = 96.7 (ball bottom at 103.7, top at 89.7). Brick top at 100.
  // The ball jumped completely over the brick (100 to 120).
  step(state, 1 / 60);
  assert.ok(state.ball.vy > 0, 'Ball should have bounced even if it tunneled');
});

