// --- Physics (movement + wall/paddle bounces) ------------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. It also handles brick collisions (swept AABB) to
// prevent tunnelling and ensure correct bounce axes.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const prevBall = { ...ball };

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Bricks collision (Swept AABB + Penetration resolution)
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    let hit = null;
    // 1. Try swept collision (for tunnelling)
    const sweep = sweepBrick(ball, prevBall, brick);
    if (sweep) {
      hit = sweep;
    } else if (collides(ball, brick)) {
      // 2. Fallback to penetration resolution (for overlap)
      hit = getOverlappingNormal(ball, brick);
    }

    if (hit) {
      const { nx, ny } = hit;

      // Bounce logic: only flip if moving TOWARDS the face
      if (nx !== 0 && (nx === LEFT && ball.vx > 0 || nx === RIGHT && ball.vx < 0)) {
        ball.vx *= -1;
      }
      if (ny !== 0 && (ny === UP && ball.vy > 0 || ny === DOWN && ball.vy < 0)) {
        ball.vy *= -1;
      }

      // Push out: reposition ball to the surface of the brick
      if (nx !== 0) {
        ball.x = nx === LEFT ? brick.x - ball.r : brick.x + brick.w + ball.r;
      }
      if (ny !== 0) {
        ball.y = ny === UP ? brick.y - ball.r : brick.y + brick.h + ball.r;
      }

      // Brick effects
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

function sweepBrick(ball, prevBall, brick) {
  const r = ball.r;
  const dx = ball.x - prevBall.x;
  const dy = ball.y - prevBall.y;

  const bL = brick.x - r;
  const bR = brick.x + brick.w + r;
  const bT = brick.y - r;
  const bB = brick.y + brick.h + r;

  const px = prevBall.x;
  const py = prevBall.y;

  let tNearX = dx === 0 ? (px < bL || px > bR ? -Infinity : Infinity) : (dx > 0 ? (bL - px) / dx : (bR - px) / dx);
  let tFarX = dx === 0 ? (px < bL || px > bR ? -Infinity : Infinity) : (dx > 0 ? (bR - px) / dx : (bL - px) / dx);
  let tNearY = dy === 0 ? (py < bT || py > bB ? -Infinity : Infinity) : (dy > 0 ? (bT - py) / dy : (bB - py) / dy);
  let tFarY = dy === 0 ? (py < bT || py > bB ? -Infinity : Infinity) : (dy > 0 ? (bB - py) / dy : (bT - py) / dy);

  if (tNearX > tFarX) [tNearX, tFarX] = [tFarX, tNearX];
  if (tNearY > tFarY) [tNearY, tFarY] = [tFarY, tNearY];

  const tEntry = Math.max(tNearX, tNearY);
  const tExit = Math.min(tFarX, tFarY);

  if (tEntry > tExit || tExit < 0 || tEntry > 1) return null;

  if (tNearX > tNearY) {
    return { nx: dx > 0 ? LEFT : RIGHT, ny: 0 };
  } else if (tNearY > tNearX) {
    return { nx: 0, ny: dy > 0 ? UP : DOWN };
  } else {
    // Corner hit: both components are equal
    return { nx: dx > 0 ? LEFT : RIGHT, ny: dy > 0 ? UP : DOWN };
  }
}

function getOverlappingNormal(ball, brick) {
  const r = ball.r;
  const overlapL = (ball.x + r) - brick.x;
  const overlapR = (brick.x + brick.w) - (ball.x - r);
  const overlapT = (ball.y + r) - brick.y;
  const overlapB = (brick.y + brick.h) - (ball.y - r);

  const minOverlap = Math.min(overlapL, overlapR, overlapT, overlapB);

  if (minOverlap === overlapL) return { nx: LEFT, ny: 0 };
  if (minOverlap === overlapR) return { nx: RIGHT, ny: 0 };
  if (minOverlap === overlapT) return { nx: 0, ny: UP };
  return { nx: 0, ny: DOWN };
}

