+    return { nx: dx > 0 ? LEFT : RIGHT, ny: 0 };
+  } else if (tNearY > tNearX) {
+    return { nx: 0, ny: dy > 0 ? UP : DOWN };
+  } else {
+    // Corner hit: both components are equal
+    return { nx: dx > 0 ? LEFT : RIGHT, ny: dy > 0 ? UP : DOWN };
+  }
+}
+
+function getOverlappingNormal(ball, brick) {
+  const r = ball.r;
+  const overlapL = (ball.x + r) - brick.x;
+  const overlapR = (brick.x + brick.w) - (ball.x - r);
+  const overlapT = (ball.y + r) - brick.y;
+  const overlapB = (brick.y + brick.h) - (ball.y - r);
+
+  const minOverlap = Math.min(overlapL, overlapR, overlapT, overlapB);
+
+  if (minOverlap === overlapL) return { nx: LEFT, ny: 0 };
+  if (minOverlap === overlapR) return { nx: RIGHT, ny: 0 };
+  if (minOverlap === overlapT) return { nx: 0, ny: UP };
+  return { nx: 0, ny: DOWN };
+}
+
 // --- Rendering (DOM): brick collision logic STILL mixed in here ------------

 // Main render loop. For each live brick we test collision AND draw in the same
 // pass: this is where logic and rendering are entangled.

