// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. It also handles brick collisions (swept AABB) to
// prevent tunnelling and ensure correct bounce axes.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const prevBall = { ...ball };

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0;
  }

  // Bricks collision (Iterative resolution to handle seams and tunneling)
  let resolved = false;
  while (!resolved) {
    let bestHit = null;
    let minT = 1.1;

    for (const brick of state.bricks) {
      if (!brick.alive) continue;

      const sweep = sweepBrick(ball, prevBall, brick);
      if (sweep && sweep.t < minT) {
        minT = sweep.t;
        bestHit = { brick, ...sweep };
      }
    }

    // If no swept hit, check for current overlap (for sticky or slow collisions)
    if (!bestHit) {
      for (const brick of state.bricks) {
        if (!brick.alive) continue;
        if (collides(ball, brick)) {
          const normal = getOverlappingNormal(ball, brick);
          bestHit = { brick, ...normal, t: 0 };
          break;
        }
      }
    }

    if (bestHit) {
      const { brick, nx, ny } = bestHit;

      if (nx !== 0 && (nx === LEFT && ball.vx > 0 || nx === RIGHT && ball.vx < 0)) {
        ball.vx *= -1;
      }
      if (ny !== 0 && (ny === UP && ball.vy > 0 || ny === DOWN && ball.vy < 0)) {
        ball.vy *= -1;
      }

      if (nx !== 0) ball.x = nx === LEFT ? brick.x - ball.r : brick.x + brick.w + ball.r;
      if (ny !== 0) ball.y = ny === UP ? brick.y - ball.r : brick.y + brick.h + ball.r;

      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);

      // After a collision, we must update prevBall to current position to avoid
      // double-bouncing or infinite loops in the same frame.
      Object.assign(prevBall, ball);
    } else {
      resolved = true;
    }
  }

  if (ball.y - ball.r > HEIGHT) return true;
  return false;
}

